The following Terraform program creates an AWS RDS MySQL database instance with its master password managed automatically by AWS Secrets Manager. It uses the default AWS Secrets Manager KMS key by omitting a custom `master_user_secret_kms_key_id`. The configuration also creates a VPC, two subnets, a DB subnet group, and a security group required for the database.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username for the RDS database."
  type        = string
  default     = "adminuser"
}

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
  default     = "db.t3.micro"
}

